  5806  static bool
  5807  load_from_sections(WASMModule *module, WASMSection *sections,
  5808                     bool is_load_from_file_buf, bool wasm_binary_freeable,
  5809                     bool no_resolve, char *error_buf, uint32 error_buf_size)
  5810  {
  5811      WASMExport *export;
  5812      WASMSection *section = sections;
  5813      const uint8 *buf, *buf_end, *buf_code = NULL, *buf_code_end = NULL,
  5814                                  *buf_func = NULL, *buf_func_end = NULL;
  5815      WASMGlobal *aux_data_end_global = NULL, *aux_heap_base_global = NULL;
  5816      WASMGlobal *aux_stack_top_global = NULL, *global;
  5817      uint64 aux_data_end = (uint64)-1LL, aux_heap_base = (uint64)-1LL,
  5818             aux_stack_top = (uint64)-1LL;
  5819      uint32 global_index, func_index, i;
  5820      uint32 aux_data_end_global_index = (uint32)-1;
  5821      uint32 aux_heap_base_global_index = (uint32)-1;
  5822      WASMFuncType *func_type;
  5823      uint8 malloc_free_io_type = VALUE_TYPE_I32;
  5824      bool reuse_const_strings = is_load_from_file_buf && !wasm_binary_freeable;
  5825      bool clone_data_seg = is_load_from_file_buf && wasm_binary_freeable;
  5826  #if WASM_ENABLE_BULK_MEMORY != 0
  5827      bool has_datacount_section = false;
  5828  #endif
  5829
  5830      /* Find code and function sections if have */
  5831      while (section) {
  5832          if (section->section_type == SECTION_TYPE_CODE) {
  5833              buf_code = section->section_body;
  5834              buf_code_end = buf_code + section->section_body_size;
  5835  #if WASM_ENABLE_DEBUG_INTERP != 0 || WASM_ENABLE_DEBUG_AOT != 0
  5836              module->buf_code = (uint8 *)buf_code;
  5837              module->buf_code_size = section->section_body_size;
  5838  #endif
  5839          }
  5840          else if (section->section_type == SECTION_TYPE_FUNC) {
  5841              buf_func = section->section_body;
  5842              buf_func_end = buf_func + section->section_body_size;
  5843          }
  5844          section = section->next;
  5845      }
  5846
  5847      section = sections;
  5848      while (section) {
  5849          buf = section->section_body;
  5850          buf_end = buf + section->section_body_size;
  5851          switch (section->section_type) {
  5852              case SECTION_TYPE_USER:
  5853                  /* unsupported user section, ignore it. */
  5854                  if (!load_user_section(buf, buf_end, module,
  5855                                         reuse_const_strings, error_buf,
  5856                                         error_buf_size))
  5857                      return false;
  5858                  break;
  5859              case SECTION_TYPE_TYPE:
  5860                  if (!load_type_section(buf, buf_end, module, error_buf,
  5861                                         error_buf_size))
  5862                      return false;
  5863                  break;
  5864              case SECTION_TYPE_IMPORT:
  5865                  if (!load_import_section(buf, buf_end, module,
  5866                                           reuse_const_strings, no_resolve,
  5867                                           error_buf, error_buf_size))
  5868                      return false;
  5869                  break;
  5870              case SECTION_TYPE_FUNC:
  5871                  if (!load_function_section(buf, buf_end, buf_code, buf_code_end,
  5872                                             module, error_buf, error_buf_size))
  5873                      return false;
  5874                  break;
  5875              case SECTION_TYPE_TABLE:
  5876                  if (!load_table_section(buf, buf_end, module, error_buf,
  5877                                          error_buf_size))
  5878                      return false;
  5879                  break;
  5880              case SECTION_TYPE_MEMORY:
  5881                  if (!load_memory_section(buf, buf_end, module, error_buf,
  5882                                           error_buf_size))
  5883                      return false;
  5884                  break;
  5885  #if WASM_ENABLE_TAGS != 0
  5886              case SECTION_TYPE_TAG:
  5887                  /* load tag declaration section */
  5888                  if (!load_tag_section(buf, buf_end, buf_code, buf_code_end,
  5889                                        module, error_buf, error_buf_size))
  5890                      return false;
  5891                  break;
  5892  #endif
  5893              case SECTION_TYPE_GLOBAL:
  5894                  if (!load_global_section(buf, buf_end, module, error_buf,
  5895                                           error_buf_size))
  5896                      return false;
  5897                  break;
  5898              case SECTION_TYPE_EXPORT:
  5899                  if (!load_export_section(buf, buf_end, module,
  5900                                           reuse_const_strings, error_buf,
  5901                                           error_buf_size))
  5902                      return false;
  5903                  break;
  5904              case SECTION_TYPE_START:
  5905                  if (!load_start_section(buf, buf_end, module, error_buf,
  5906                                          error_buf_size))
  5907                      return false;
  5908                  break;
  5909              case SECTION_TYPE_ELEM:
  5910                  if (!load_table_segment_section(buf, buf_end, module, error_buf,
  5911                                                  error_buf_size))
  5912                      return false;
  5913                  break;
  5914              case SECTION_TYPE_CODE:
  5915                  if (!load_code_section(buf, buf_end, buf_func, buf_func_end,
  5916                                         module, error_buf, error_buf_size))
  5917                      return false;
  5918                  break;
  5919              case SECTION_TYPE_DATA:
  5920                  if (!load_data_segment_section(buf, buf_end, module,
  5921  #if WASM_ENABLE_BULK_MEMORY != 0
  5922                                                 has_datacount_section,
  5923  #endif
  5924                                                 clone_data_seg, error_buf,
  5925                                                 error_buf_size))
  5926                      return false;
  5927                  break;
  5928  #if WASM_ENABLE_BULK_MEMORY != 0
  5929              case SECTION_TYPE_DATACOUNT:
  5930                  if (!load_datacount_section(buf, buf_end, module, error_buf,
  5931                                              error_buf_size))
  5932                      return false;
  5933                  has_datacount_section = true;
  5934                  break;
  5935  #endif
  5936  #if WASM_ENABLE_STRINGREF != 0
  5937              case SECTION_TYPE_STRINGREF:
  5938                  if (!load_stringref_section(buf, buf_end, module,
  5939                                              reuse_const_strings, error_buf,
  5940                                              error_buf_size))
  5941                      return false;
  5942                  break;
  5943  #endif
  5944              default:
  5945                  set_error_buf(error_buf, error_buf_size, "invalid section id");
  5946                  return false;
  5947          }
  5948
  5949          section = section->next;
  5950      }
  5951
  5952  #if WASM_ENABLE_BULK_MEMORY != 0
  5953      if (!check_data_count_consistency(
  5954              has_datacount_section, module->data_seg_count1,
  5955              module->data_seg_count, error_buf, error_buf_size)) {
  5956          return false;
  5957      }
  5958  #endif
  5959
  5960      module->aux_data_end_global_index = (uint32)-1;
  5961      module->aux_heap_base_global_index = (uint32)-1;
  5962      module->aux_stack_top_global_index = (uint32)-1;
  5963
  5964      /* Resolve auxiliary data/stack/heap info and reset memory info */
  5965      export = module->exports;
  5966      for (i = 0; i < module->export_count; i++, export ++) {
  5967          if (export->kind == EXPORT_KIND_GLOBAL) {
  5968              if (!strcmp(export->name, "__heap_base")) {
  5969                  if (export->index < module->import_global_count) {
  5970                      LOG_DEBUG("Skip the process if __heap_base is imported "
  5971                                "instead of being a local global");
  5972                      continue;
  5973                  }
  5974
  5975                  /* only process linker-generated symbols */
  5976                  global_index = export->index - module->import_global_count;
  5977                  global = module->globals + global_index;
  5978                  if (global->type.val_type == VALUE_TYPE_I32
  5979                      && !global->type.is_mutable
  5980                      && global->init_expr.init_expr_type
  5981                             == INIT_EXPR_TYPE_I32_CONST) {
  5982                      aux_heap_base_global = global;
  5983                      aux_heap_base = (uint64)(uint32)global->init_expr.u.i32;
  5984                      aux_heap_base_global_index = export->index;
  5985                      LOG_VERBOSE("Found aux __heap_base global, value: %" PRIu64,
  5986                                  aux_heap_base);
  5987                  }
  5988              }
  5989              else if (!strcmp(export->name, "__data_end")) {
  5990                  if (export->index < module->import_global_count) {
  5991                      LOG_DEBUG("Skip the process if __data_end is imported "
  5992                                "instead of being a local global");
  5993                      continue;
  5994                  }
  5995
  5996                  /* only process linker-generated symbols */
  5997                  global_index = export->index - module->import_global_count;
  5998                  global = module->globals + global_index;
  5999                  if (global->type.val_type == VALUE_TYPE_I32
  6000                      && !global->type.is_mutable
  6001                      && global->init_expr.init_expr_type
  6002                             == INIT_EXPR_TYPE_I32_CONST) {
  6003                      aux_data_end_global = global;
  6004                      aux_data_end = (uint64)(uint32)global->init_expr.u.i32;
  6005                      aux_data_end_global_index = export->index;
  6006                      LOG_VERBOSE("Found aux __data_end global, value: %" PRIu64,
  6007                                  aux_data_end);
  6008
  6009                      aux_data_end = align_uint64(aux_data_end, 16);
  6010                  }
  6011              }
  6012
  6013              /* For module compiled with -pthread option, the global is:
  6014                  [0] stack_top       <-- 0
  6015                  [1] tls_pointer
  6016                  [2] tls_size
  6017                  [3] data_end        <-- 3
  6018                  [4] global_base
  6019                  [5] heap_base       <-- 5
  6020                  [6] dso_handle
  6021
  6022                  For module compiled without -pthread option:
  6023                  [0] stack_top       <-- 0
  6024                  [1] data_end        <-- 1
  6025                  [2] global_base
  6026                  [3] heap_base       <-- 3
  6027                  [4] dso_handle
  6028              */
  6029              if (aux_data_end_global && aux_heap_base_global
  6030                  && aux_data_end <= aux_heap_base) {
  6031                  module->aux_data_end_global_index = aux_data_end_global_index;
  6032                  module->aux_data_end = aux_data_end;
  6033                  module->aux_heap_base_global_index = aux_heap_base_global_index;
  6034                  module->aux_heap_base = aux_heap_base;
  6035
  6036                  /* Resolve aux stack top global */
  6037                  for (global_index = 0; global_index < module->global_count;
  6038                       global_index++) {
  6039                      global = module->globals + global_index;
  6040                      if (global->type.is_mutable /* heap_base and data_end is
  6041                                                not mutable */
  6042                          && global->type.val_type == VALUE_TYPE_I32
  6043                          && global->init_expr.init_expr_type
  6044                                 == INIT_EXPR_TYPE_I32_CONST
  6045                          && (uint64)(uint32)global->init_expr.u.i32
  6046                                 <= aux_heap_base) {
  6047                          aux_stack_top_global = global;
  6048                          aux_stack_top = (uint64)(uint32)global->init_expr.u.i32;
  6049                          module->aux_stack_top_global_index =
  6050                              module->import_global_count + global_index;
  6051                          module->aux_stack_bottom = aux_stack_top;
  6052                          module->aux_stack_size =
  6053                              aux_stack_top > aux_data_end
  6054                                  ? (uint32)(aux_stack_top - aux_data_end)
  6055                                  : (uint32)aux_stack_top;
  6056                          LOG_VERBOSE(
  6057                              "Found aux stack top global, value: %" PRIu64 ", "
  6058                              "global index: %d, stack size: %d",
  6059                              aux_stack_top, global_index,
  6060                              module->aux_stack_size);
  6061                          break;
  6062                      }
  6063                  }
  6064                  if (!aux_stack_top_global) {
  6065                      /* Auxiliary stack global isn't found, it must be unused
  6066                         in the wasm app, as if it is used, the global must be
  6067                         defined. Here we set it to __heap_base global and set
  6068                         its size to 0. */
  6069                      aux_stack_top_global = aux_heap_base_global;
  6070                      aux_stack_top = aux_heap_base;
  6071                      module->aux_stack_top_global_index =
  6072                          module->aux_heap_base_global_index;
  6073                      module->aux_stack_bottom = aux_stack_top;
  6074                      module->aux_stack_size = 0;
  6075                  }
  6076                  break;
  6077              }
  6078          }
  6079      }
  6080
  6081      module->malloc_function = (uint32)-1;
  6082      module->free_function = (uint32)-1;
  6083      module->retain_function = (uint32)-1;
  6084
  6085      /* Resolve malloc/free function exported by wasm module */
  6086  #if WASM_ENABLE_MEMORY64 != 0
  6087      if (has_module_memory64(module))
  6088          malloc_free_io_type = VALUE_TYPE_I64;
  6089  #endif
  6090      export = module->exports;
  6091      for (i = 0; i < module->export_count; i++, export ++) {
  6092          if (export->kind == EXPORT_KIND_FUNC) {
  6093              if (!strcmp(export->name, "malloc")
  6094                  && export->index >= module->import_function_count) {
  6095                  func_index = export->index - module->import_function_count;
  6096                  func_type = module->functions[func_index]->func_type;
  6097                  if (func_type->param_count == 1 && func_type->result_count == 1
  6098                      && func_type->types[0] == malloc_free_io_type
  6099                      && func_type->types[1] == malloc_free_io_type) {
  6100                      bh_assert(module->malloc_function == (uint32)-1);
  6101                      module->malloc_function = export->index;
  6102                      LOG_VERBOSE("Found malloc function, name: %s, index: %u",
  6103                                  export->name, export->index);
  6104                  }
  6105              }
  6106              else if (!strcmp(export->name, "__new")
  6107                       && export->index >= module->import_function_count) {
  6108                  /* __new && __pin for AssemblyScript */
  6109                  func_index = export->index - module->import_function_count;
  6110                  func_type = module->functions[func_index]->func_type;
  6111                  if (func_type->param_count == 2 && func_type->result_count == 1
  6112                      && func_type->types[0] == malloc_free_io_type
  6113                      && func_type->types[1] == VALUE_TYPE_I32
  6114                      && func_type->types[2] == malloc_free_io_type) {
  6115                      uint32 j;
  6116                      WASMExport *export_tmp;
  6117
  6118                      bh_assert(module->malloc_function == (uint32)-1);
  6119                      module->malloc_function = export->index;
  6120                      LOG_VERBOSE("Found malloc function, name: %s, index: %u",
  6121                                  export->name, export->index);
  6122
  6123                      /* resolve retain function.
  6124                         If not found, reset malloc function index */
  6125                      export_tmp = module->exports;
  6126                      for (j = 0; j < module->export_count; j++, export_tmp++) {
  6127                          if ((export_tmp->kind == EXPORT_KIND_FUNC)
  6128                              && (!strcmp(export_tmp->name, "__retain")
  6129                                  || (!strcmp(export_tmp->name, "__pin")))
  6130                              && (export_tmp->index
  6131                                  >= module->import_function_count)) {
  6132                              func_index = export_tmp->index
  6133                                           - module->import_function_count;
  6134                              func_type =
  6135                                  module->functions[func_index]->func_type;
  6136                              if (func_type->param_count == 1
  6137                                  && func_type->result_count == 1
  6138                                  && func_type->types[0] == malloc_free_io_type
  6139                                  && func_type->types[1] == malloc_free_io_type) {
  6140                                  bh_assert(module->retain_function
  6141                                            == (uint32)-1);
  6142                                  module->retain_function = export_tmp->index;
  6143                                  LOG_VERBOSE("Found retain function, name: %s, "
  6144                                              "index: %u",
  6145                                              export_tmp->name,
  6146                                              export_tmp->index);
  6147                                  break;
  6148                              }
  6149                          }
  6150                      }
  6151                      if (j == module->export_count) {
  6152                          module->malloc_function = (uint32)-1;
  6153                          LOG_VERBOSE("Can't find retain function,"
  6154                                      "reset malloc function index to -1");
  6155                      }
  6156                  }
  6157              }
  6158              else if (((!strcmp(export->name, "free"))
  6159                        || (!strcmp(export->name, "__release"))
  6160                        || (!strcmp(export->name, "__unpin")))
  6161                       && export->index >= module->import_function_count) {
  6162                  func_index = export->index - module->import_function_count;
  6163                  func_type = module->functions[func_index]->func_type;
  6164                  if (func_type->param_count == 1 && func_type->result_count == 0
  6165                      && func_type->types[0] == malloc_free_io_type) {
  6166                      bh_assert(module->free_function == (uint32)-1);
  6167                      module->free_function = export->index;
  6168                      LOG_VERBOSE("Found free function, name: %s, index: %u",
  6169                                  export->name, export->index);
  6170                  }
  6171              }
  6172          }
  6173      }
  6174
  6175  #if WASM_ENABLE_FAST_INTERP != 0 && WASM_ENABLE_LABELS_AS_VALUES != 0
  6176      handle_table = wasm_interp_get_handle_table();
  6177  #endif
  6178
  6179      for (i = 0; i < module->function_count; i++) {
  6180          WASMFunction *func = module->functions[i];
  6181          if (!wasm_loader_prepare_bytecode(module, func, i, error_buf,
  6182                                            error_buf_size)) {
  6183              return false;
  6184          }
  6185
  6186          if (i == module->function_count - 1
  6187              && func->code + func->code_size != buf_code_end) {
  6188              set_error_buf(error_buf, error_buf_size,
